//! Is an address Valve's, and which Steam relay site is it at?
//!
//! # Why this exists
//!
//! Steam doesn't always say when a session is relayed. In one reporting mode
//! (seen in experiment E2) `GetP2PSessionState` says "not relayed" but gives
//! the relay server's own address as the remote. Knowing Valve's address
//! space turns that address into evidence of a relay (detector **L** in
//! `relay.rs`), and knowing Valve's relay sites names and places it.
//!
//! # Where the data comes from
//!
//! `valve_data.rs` is generated by `analysis/valve_prefixes.py` from two
//! public sources: the IPv4 prefixes Valve's network (AS32590) announces,
//! from RIPEstat, and Steam's relay network config for Dark Souls III. The
//! header of that file records the sources and the date. Address space
//! changes slowly, but the file should be regenerated now and then.
//!
//! Relay sites are matched by **/24**: the relays seen in E1/E2 aren't in
//! Steam's published list themselves, but sit in the same /24 as a listed
//! site's relays (for example the Seattle site).

use crate::valve_data::{POPS, Pop, VALVE_V4_PREFIXES};
use std::net::Ipv4Addr;

/// Valve's autonomous system number (used with the optional ASN database).
pub const VALVE_ASN: u32 = 32590;

/// True if `ip` lies in a prefix announced by Valve's network.
pub fn is_valve(ip: Ipv4Addr) -> bool {
    let x = u32::from(ip);
    VALVE_V4_PREFIXES.iter().any(|&(net, len)| {
        // A /len mask: the top `len` bits set. `checked_shl` avoids the
        // overflow a shift by 32 would cause (a /0 prefix matches everything).
        let mask = u32::MAX.checked_shl(32 - len as u32).unwrap_or(0);
        x & mask == u32::from(Ipv4Addr::from(net)) & mask
    })
}

/// The Steam relay site whose listed relays share `ip`'s /24, if any.
pub fn site(ip: Ipv4Addr) -> Option<&'static Pop> {
    let o = ip.octets();
    POPS.iter()
        .find(|p| p.nets24.iter().any(|n| n[..] == o[..3]))
}

/// Detector **L**: `ip` is in Valve's address space **or** at a listed
/// Steam relay site. The second part matters because some sites are hosted
/// by partners (e.g. Datapacket) on addresses Valve doesn't announce.
pub fn is_relay_address(ip: Ipv4Addr) -> bool {
    is_valve(ip) || site(ip).is_some()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn seattle_relay_block_is_valve_at_seattle() {
        // E1/E2 relays sat in this /24, next to the site's listed relays.
        for last in [1, 200] {
            let ip = Ipv4Addr::new(205, 196, 6, last);
            assert!(is_valve(ip));
            assert_eq!(site(ip).map(|p| p.code), Some("sea"));
        }
    }

    #[test]
    fn lan_documentation_and_public_dns_are_not_valve() {
        for ip in [
            Ipv4Addr::new(192, 168, 1, 15),
            Ipv4Addr::new(203, 0, 113, 9),
            Ipv4Addr::new(8, 8, 8, 8),
        ] {
            assert!(!is_valve(ip), "{ip}");
            assert!(site(ip).is_none());
        }
    }

    #[test]
    fn hosting_flag_matches_valve_space_and_every_site_counts_for_l() {
        for p in POPS {
            for n in p.nets24 {
                let ip = Ipv4Addr::new(n[0], n[1], n[2], 1);
                assert_eq!(is_valve(ip), p.valve_hosted, "{} {ip}", p.code);
                assert!(is_relay_address(ip), "{} {ip}", p.code);
            }
        }
    }

    #[test]
    fn partner_site_seen_in_runs_is_a_relay_address() {
        // The game itself sent a few packets to this partner site (E2 runs).
        let ip = Ipv4Addr::new(212, 102, 63, 139);
        assert!(!is_valve(ip));
        assert!(is_relay_address(ip));
        assert_eq!(site(ip).map(|p| p.code), Some("dlhr"));
    }
}
